import{z as o,x as i,o as A,c as C,q as l,j as r,D as a,d as e,s,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"安全过滤","description":"","frontmatter":{"title":"安全过滤","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-safety-filtering.md","filePath":"llm/mm-safety-filtering.md","lastUpdated":1791063341000}'),m={name:"llm/mm-safety-filtering.md"};function D(d,E,p,F,h,f){const t=i("Mermaid");return A(),C("div",null,[E[2]||(E[2]=l('<h1 id="安全过滤" tabindex="-1">安全过滤 <a class="header-anchor" href="#安全过滤" aria-label="Permalink to &quot;安全过滤&quot;">​</a></h1><div class="epigraph"><p>只扫文本的护栏，在图像流量里等于只检了行李的一半；而图里那半，往往还写着字。</p><footer>—— 据 Shan et al., 2020（对抗性视觉防护）与多模态红队、护栏系统文献整理</footer></div><p><a href="/llm/mm-eval-serving">上一课</a>立了评测协议，本课写线上另一道闸：安全过滤。多模态流量的审核面比文本宽：像素本身、图里嵌的字、视频每一帧、语音内容。跨模态越狱的通道错位已由<a href="/llm/multimodal-jailbreak">多模态越狱</a>专文写过——对齐大多做在文本指令上，视觉 token 是护栏盲区；本课不再论证漏洞，只写过滤管线的落地：入口怎么筛、输出怎么拦、延迟与误杀怎么不失控。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>输入面至少三层。<strong>像素层</strong>：违规图像内容的视觉识别，经典分类任务。<strong>图内文本层</strong>：把违规指令印进图片是最省事的攻击——像素分类器看不见语义，文本审核看不见图，两条防线恰好都错过；主模型却看得清清楚楚，并照做。<strong>旁路层</strong>：文件名、EXIF 描述、链接预览，不进模型，但进日志与聚合系统。输出面同样双向：对图的描述可能复述敏感内容，OCR 类任务的输出就是原文搬运——图里有什么违规文本，输出里就有什么。</p><p><span class="marginnote">「旁路层」里的 EXIF 是照片自带的元数据小卡片：拍摄时间、GPS 位置、设备型号都记在里面。它不进模型的「眼睛」，但会进日志与聚合系统——就像信封不会被读信，可信封上写着寄信人住址，泄密往往从信封开始。</span></p><p>过滤还有自己的服务问题：审核也要算力。高分辨率审核串在关键路径上会把<a href="/llm/ttft">首 token 延迟</a>翻倍；砍审核分辨率，小字违规就留给主模型去看——防线与被保护对象用着不同分辨率档，这本身就是漏洞。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管线按成本分层。<strong>入口粗筛</strong>便宜且快：内容 hash 黑名单加低分辨率快速分类器，多数正常流量到此放行。<strong>细筛</strong>只对可疑或命中风险类目的请求开：高分辨率重筛、跑 OCR、图内文本汇入统一的文本审核流。关键是<strong>联动</strong>而非并联：图内文本须与用户提示合并成同一条待审文本，违规性常在「图 + 问法」的组合里成立——普通海报配上「照着图里的字做」就是攻击。输出侧流式过滤沿用流式 stop 的挂起思想：增量过分类器，可能构成违规前缀的尾巴挂起不提交，确认安全再放行；判定违规则切断并给固定拒绝话术。审核决策全落审计日志，是申诉与红队回归的共同底座。</p><p><span class="marginnote">审核分辨率的两难：粗筛用 512px 档时，图内小号字的违规指令在像素层面已不可读，躲过审核；主模型却用 1344px 档看图，同一行字看得一清二楚。审核档位不得低于主模型实际可能用到的档位。</span></p>',10)),(A(),r(n,null,{default:a(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E8%AF%B7%E6%B1%82%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20HASH%7B%22hash%20%E9%BB%91%E5%90%8D%E5%8D%95%3F%22%7D%0A%20%20HASH%20--%3E%7C%E5%91%BD%E4%B8%AD%7C%20DENY%5B%22%E7%9B%B4%E6%8E%A5%E6%8B%92%E7%BB%9D%22%5D%0A%20%20HASH%20--%3E%7C%E6%9C%AA%E5%91%BD%E4%B8%AD%7C%20FAST%5B%22%E4%BD%8E%E5%88%86%E8%BE%A8%E7%8E%87%E5%BF%AB%E9%80%9F%E5%88%86%E7%B1%BB%22%5D%0A%20%20FAST%20--%3E%20RISK%7B%22%E5%8F%AF%E7%96%91%3F%22%7D%0A%20%20RISK%20--%3E%7C%E5%90%A6%7C%20PASS%5B%22%E6%94%BE%E8%A1%8C%E4%B8%BB%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20RISK%20--%3E%7C%E6%98%AF%7C%20OCR%5B%22%E9%AB%98%E5%88%86%E8%BE%A8%E7%8E%87%E7%BB%86%E7%AD%9B%E5%8A%A0%20OCR%22%5D%0A%20%20OCR%20--%3E%20TXT%5B%22%E5%9B%BE%E5%86%85%E6%96%87%E6%9C%AC%E5%B9%B6%E5%85%A5%E6%96%87%E6%9C%AC%E5%AE%A1%E6%A0%B8%22%5D%0A%20%20TXT%20--%3E%20RISK2%7B%22%E7%BB%84%E5%90%88%E8%BF%9D%E8%A7%84%3F%22%7D%0A%20%20RISK2%20--%3E%7C%E6%98%AF%7C%20DENY%0A%20%20RISK2%20--%3E%7C%E5%90%A6%7C%20PASS%0A%20%20PASS%20--%3E%20GEN%5B%22%E6%A8%A1%E5%9E%8B%E6%B5%81%E5%BC%8F%E8%BE%93%E5%87%BA%22%5D%0A%20%20GEN%20--%3E%20OF%7B%22%E8%BE%93%E5%87%BA%E5%88%86%E7%B1%BB%22%7D%0A%20%20OF%20--%3E%7C%22%E5%8F%AF%E7%96%91%E5%89%8D%E7%BC%80%22%7C%20HOLD%5B%22%E6%8C%82%E8%B5%B7%E5%BE%85%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20OF%20--%3E%7C%E5%AE%89%E5%85%A8%7C%20EMIT%5B%22%E6%8F%90%E4%BA%A4%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"级联的经济学由错误成本的不对称决定：漏检的代价远高于误杀的体验代价，所以粗筛按高召回配阈值，细筛补精度。粗筛的分辨率与类目集是调参重点：类目开太多，粗筛变细筛，延迟崩；开太少，细筛触发率形同虚设。图内文本联动则是结构上的必然：违规性不在单一模态里，单通道分类器的最优阈值救不了通道缺失——先合流再审核，是唯一结构上站得住的做法。",-1)),E[5]||(E[5]=B("p",null,[B("span",{class:"marginnote"},"级联为什么省钱？设粗筛单价 1、细筛单价 10：一百个请求若全员细筛要 1000；级联后是 100×1 + 5×10 = 150，省近 7 倍。前提是粗筛别漏——这正是「高召回」配在粗筛、精度交给细筛的原因。")],-1)),(A(),r(n,null,{default:a(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%7B%22%E7%B2%97%E7%AD%9B%E9%98%88%E5%80%BC%E5%BE%80%E5%93%AA%E8%BE%B9%E8%B0%83%3F%22%7D%0A%20%20T%20--%3E%7C%22%E8%B0%83%E4%B8%A5%EF%BC%9A%E5%AE%81%E9%94%99%E6%9D%80%22%7C%20HI%5B%22%E8%AF%AF%E6%9D%80%E4%B8%8A%E5%8D%87%EF%BC%8C%E6%AD%A3%E5%B8%B8%E8%AF%B7%E6%B1%82%E8%A2%AB%E6%8B%A6%22%5D%0A%20%20T%20--%3E%7C%22%E8%B0%83%E6%9D%BE%EF%BC%9A%E5%AE%81%E6%94%BE%E8%BF%87%22%7C%20LO%5B%22%E6%BC%8F%E6%A3%80%E4%B8%8A%E5%8D%87%EF%BC%8C%E8%BF%9D%E8%A7%84%E8%BF%9B%E4%B8%BB%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20HI%20--%3E%20C1%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%94%B3%E8%AF%89%E4%B8%8E%E4%BD%93%E9%AA%8C%E5%8F%97%E6%8D%9F%EF%BC%8C%E5%8F%AF%E4%BA%8B%E5%90%8E%E7%BA%A0%E9%94%99%22%5D%0A%20%20LO%20--%3E%20C2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E8%BF%9D%E8%A7%84%E5%86%85%E5%AE%B9%E5%87%BA%E8%A1%97%EF%BC%8C%E6%94%B6%E4%B8%8D%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20C1%20--%3E%20B%5B%22%E5%AE%89%E5%85%A8%E4%BE%A7%E9%BB%98%E8%AE%A4%EF%BC%9A%E7%B2%97%E7%AD%9B%E9%AB%98%E5%8F%AC%E5%9B%9E%EF%BC%8C%E7%BB%86%E7%AD%9B%E8%A1%A5%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20C2%20--%3E%20B%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p>流式过滤的难点是「部分文本不可分类」：半句话可能同时是违规句和正常句的前缀。挂起窗口由分类器的不确定区决定，与<a href="/llm/stop-sequences">流式 stop 匹配</a>同构——都在「早提交的闪错」与「晚提交的卡顿」之间取窗口。类目多、模式互为前缀时窗口变长，用户感知为吐字一顿一顿，这是输出过滤的真实延迟成本。<span class="marginnote">挂起窗口类比输入法打字：拼音打到一半时，这串字母既可能变成好词也可能变成错词，系统先不上屏、等你打完再定。流式过滤同理——前缀同时是违规句和正常句的开头时，必须多等几个 token 才能判定，等的那几十毫秒就是安全的价格。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>过滤是概率防线：对抗扰动、艺术字体、逐帧拆分进视频，攻防还在升级，红队要持续跑（<a href="/llm/aeval-redteam-engineering">红队工程</a>口径直接适用），规则变更都过回归集。误杀侧同样有度量：过度拒绝率要与漏检率一起进<a href="/llm/aeval-safety-benchmark-design">安全评测</a>报告，只报拦截量是在做业绩不做事。审核图像的留存设期限与用途边界，为申诉保留的素材不该变成训练数据。语音面另有法规红线：实时通话的内容过滤先过法务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>输入面三层：像素、图内文本、旁路元数据；图内文本是文本护栏的经典盲区。</li><li>级联过滤：hash 黑名单加低分辨率粗筛保延迟，可疑流才进高分辨率细筛。</li><li>图内文本与用户提示合流审核，违规性常在图文组合里成立。</li><li>审核分辨率不得低于主模型可用档位，否则防线比被保护对象先失明。</li><li>输出过滤挂起可疑前缀，窗口是延迟与安全的折中；决策全落审计日志。</li><li>出处：据多模态越狱与红队文献、对抗性视觉防护（Shan et al., 2020）及安全评测课程口径整理。</li></ul>',5))])}const u=o(m,[["render",D]]);export{g as __pageData,u as default};
